{
  "template": "trigger"
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "penguins",
        "admissions"
      ]
    }
  ]
}

attribute "tsugumi";
namespace simpson;
table Penguins { value:string; }
table Outputs { penguins:Penguins (required, tsugumi: "file"); }
root_type Outputs;

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; packages = ps: [ ps.palmerpenguins ]; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "start"
    }
  ],
  "retainArtifact": true,
  "artifactOutput": "penguins",
  "filesystem": true
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "correlate",
        "survey"
      ]
    }
  ]
}

attribute "tsugumi";
namespace simpson;
table Points { value:string; }
table Correlations { value:string; }
table Outputs { points:Points (required, tsugumi: "file"); correlations:Correlations (required, tsugumi: "file"); }
root_type Outputs;

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "penguins"
    }
  ],
  "retainArtifact": true,
  "artifactOutput": "correlations",
  "filesystem": true,
  "params": [
    {
      "name": "stratify",
      "type": "string",
      "data": "species"
    }
  ]
}

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; packages = ps: [ ps.ggplot2 ]; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "points"
    },
    {
      "name": "correlations"
    }
  ]
}

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; packages = ps: [ ps.ggplot2 ]; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "penguins"
    }
  ]
}

